starterCode.css:
/* TransitionGroup 动画 */
.card-enter-active,
.card-leave-active {
  transition: all 0.5s ease;
}
.card-enter-from {
  opacity: 0;
  transform: translateY(30px);
}
.card-leave-to {
  opacity: 0;
  transform: scale(0.8);
}
.card-leave-active {
  position: absolute;
}
.card-move {
  transition: transform 0.5s ease;
}

/* 空状态 */
.empty-state {
  text-align: center;
  padding: 60px 20px;
  color: #999;
}

/* 小屏幕适配 */
@media (max-width: 480px) {
  .music-card {
    flex-direction: column;
    text-align: center;
  }
  .card-actions {
    justify-content: center;
  }
}
